<?php declare(strict_types=1); namespace Modules\Media\Models; use Core\Database\Model; class Media extends Model { protected static string $table = 'media'; protected static array $fillable = [ 'collection', 'filename', 'original_name', 'path', 'mime_type', 'extension', 'size', 'meta', 'owner_id', 'status', ]; protected static array $casts = [ 'id' => 'int', 'size' => 'int', 'meta' => 'json', ]; public function isImage(): bool { return str_starts_with((string) $this->mime_type, 'image/'); } public function isDocument(): bool { return in_array($this->extension, ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'csv', 'txt'], true); } public function isVideo(): bool { return str_starts_with((string) $this->mime_type, 'video/'); } } 